import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Camera, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, CloudCheck, CreditCard, Download, FileSpreadsheet, FileText, History, ImagePlus, LayoutGrid, LoaderCircle, Package, Pencil, Plus, RefreshCw, Search, ShoppingBag, SlidersHorizontal, Sparkles, Trash2, Upload, Users, Wallet, X } from "lucide-react";
