function ExchangeForm({ order, onClose, onSaved }: { order: Order; onClose: () => void; onSaved: () => Promise<void> }) {
  const [article, setArticle] = useState(order.article), [quantity, setQuantity] = useState(String(order.quantity)), [price, setPrice] = useState(String(order.unitCents / 100));
  const [file, setFile] = useState<File | null>(null), [savedPreview] = useState(order ? resolvePhotoUrl(order) : ""), [busy, setBusy] = useState(false), [error, setError] = useState("");
  const preview = useMemo(() => file ? URL.createObjectURL(file) : savedPreview, [file, savedPreview]);
  useEffect(() => () => { if (file) URL.revokeObjectURL(preview); }, [file, preview]);
  const nextTotal = Number(quantity) * moneyInput(price) + order.extraCents - order.discountCents;
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    if (!article.trim() || !Number.isInteger(Number(quantity)) || Number(quantity) < 1 || !Number.isSafeInteger(moneyInput(price)) || moneyInput(price) < 0 || nextTotal < 0) { setError("Revisa el artículo, la cantidad y el precio a cobrar."); return; }
    setBusy(true); setError("");
    try { let photoKey = order.photoKey; if (file) { const data = new FormData(); data.append("file", file); photoKey = (await api<{photoKey: string}>("/api/photos", { method: "POST", body: data })).photoKey; } await api(`/api/orders/${encodeURIComponent(order.id)}/exchange`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision: order.revision, article: article.trim(), unitCents: moneyInput(price), quantity: Number(quantity), photoKey, notes: String(form.get("notes") || "").trim(), date: String(form.get("date")) }) }); await onSaved(); onClose(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo registrar el cambio."); } finally { setBusy(false); }
  }
  return <Modal title="Cambiar un artículo" subtitle={`Para ${order.client}. Sus pagos y el historial se conservarán.`} onClose={onClose}><form onSubmit={submit}><div className="form-body"><div className="exchange-box"><strong>Artículo anterior: {order.article}</strong><p>Total anterior: {currency(totalOf(order))}</p></div><label className="field" style={{marginTop:20}}>Nuevo artículo <span className="required">*</span><input value={article} onChange={event => setArticle(event.target.value)} required maxLength={200}/></label><div className="field-row"><label className="field quantity-field">Cantidad<input value={quantity} onChange={event => setQuantity(event.target.value)} type="number" min="1" max="9999" step="1" required/></label><label className="field">Precio a cobrar por unidad (RD$)<input value={price} onChange={event => setPrice(event.target.value)} type="number" min="0" step="0.01" required/></label></div><label className="field">Foto del nuevo artículo (opcional)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={event => { const next = event.target.files?.[0]; if (!next) return; if (!["image/jpeg", "image/png", "image/webp"].includes(next.type) || next.size > 5 * 1024 * 1024) { setError("Elige una foto JPG, PNG o WebP de hasta 5 MB."); return; } setFile(next); setError(""); }}/>{preview && <img src={preview} alt="Artículo del cambio" style={{width:96,height:96,objectFit:"contain",borderRadius:8}}/>}</label><label className="field">Fecha del cambio<input name="date" type="date" defaultValue={today()} required/></label><label className="field">Motivo o nota del cambio<textarea name="notes" rows={3} maxLength={2000} placeholder="Ej. Cambio de talla o de modelo"/></label><div className="form-total"><span>Nuevo precio a cobrar</span><strong>{currency(nextTotal)}</strong></div><p className="people-tip">Diferencia: {nextTotal >= totalOf(order) ? "+" : "−"}{currency(Math.abs(nextTotal - totalOf(order)))}. Se conservan los cargos y descuentos del artículo.</p>{error && <div className="inline-error" role="alert">{error}</div>}</div><div className="modal-footer"><button type="button" className="button button-plain" disabled={busy} onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary" disabled={busy}>{busy ? <LoaderCircle className="spin" size={16}/> : <RefreshCw size={16}/>} {busy ? "Guardando…" : "Confirmar cambio"}</button></div></form></Modal>;
}

function ClientReceipt({ orders, payments, onClose }: { orders: Order[]; payments: Payment[]; onClose: () => void }) {
  const client = orders[0]; if (!client) return null;
  const ids = new Set(orders.map(order => order.id)); const moves = payments.filter(payment => ids.has(payment.orderId));
  const total = orders.reduce((sum, order) => sum + totalOf(order), 0), paid = orders.reduce((sum, order) => sum + paidFor(order.id, payments), 0), balance = total - paid;
  return <Modal title="Comprobante de pedido" subtitle="Vista para imprimir o guardar como PDF." onClose={onClose} wide><div className="form-body print-receipt"><div className="invoice-heading"><h3>mi encargo<span className="brand-dot">.</span></h3><p>Comprobante de pedido · {dateLabel(today())}<br/>Importes en pesos dominicanos (RD$)</p></div><div className="invoice-person"><div><span>Cliente</span><strong>{client.client}</strong>{client.phone && <span>{client.phone}</span>}</div><div>{orders.length} {orders.length === 1 ? "artículo" : "artículos"}</div></div><table className="invoice-table"><thead><tr><th>Artículo</th><th>Cant.</th><th>Precio ud.</th><th>Importe</th></tr></thead><tbody>{orders.map(order => <tr key={order.id}><td>{order.article}<small>{order.platform} · {order.status}{order.variant ? ` · ${order.variant}` : ""}</small>{(order.extraCents > 0 || order.discountCents > 0) && <small>Cargo: {currency(order.extraCents)} · Descuento: {currency(order.discountCents)}</small>}</td><td>{order.quantity}</td><td>{currency(order.unitCents)}</td><td>{currency(totalOf(order))}</td></tr>)}</tbody></table><div className="receipt"><div className="receipt-total"><strong>Total a cobrar</strong><strong>{currency(total)}</strong></div><div><span>Abonos recibidos</span><span>{currency(moves.filter(payment => payment.kind !== "Devolución").reduce((sum, payment) => sum + payment.amountCents, 0))}</span></div><div><span>Devoluciones realizadas</span><span>{currency(moves.filter(payment => payment.kind === "Devolución").reduce((sum, payment) => sum + payment.amountCents, 0))}</span></div><div><span>Pagado por cliente (neto)</span><span>{currency(paid)}</span></div><div className={`receipt-balance ${balance < 0 ? "credit-note" : ""}`}><strong>{balance < 0 ? "Saldo a favor del cliente" : "Saldo pendiente"}</strong><strong>{currency(Math.abs(balance))}</strong></div></div>{moves.length > 0 && <><div className="section-label"><h3>Movimientos del cliente</h3></div><table className="invoice-table"><thead><tr><th>Fecha</th><th>Movimiento</th><th>Forma de pago</th><th>Monto</th></tr></thead><tbody>{[...moves].sort((a,b) => a.date.localeCompare(b.date)).map(payment => <tr key={payment.id}><td>{dateLabel(payment.date)}</td><td>{payment.kind}{payment.note && <small>{payment.note}</small>}</td><td>{payment.method}</td><td>{payment.kind === "Devolución" ? "−" : "+"}{currency(payment.amountCents)}</td></tr>)}</tbody></table></>}<p className="invoice-note">Los artículos cancelados no suman al total. Los abonos se conservan y las devoluciones registradas reducen el pagado neto.<br/>Comprobante de control de pedidos; sin valor fiscal.</p></div><div className="modal-footer"><button className="button button-plain" onClick={onClose}>Cerrar</button><button className="button button-primary" onClick={() => window.print()}><Download size={16}/> Imprimir / Guardar PDF</button></div></Modal>;
}

