  const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const [query, setQuery] = useState(""), [status, setStatus] = useState("Todos"), [onlyPending, setOnlyPending] = useState(false), [clientFilter, setClientFilter] = useState("");
  const [form, setForm] = useState<"new" | Order | null>(null), [detailId, setDetailId] = useState<string | null>(null), [paymentOrder, setPaymentOrder] = useState<Order | null>(null);
  const [help, setHelp] = useState(false); const [exchangeOrder, setExchangeOrder] = useState<Order | null>(null); const [receiptKey, setReceiptKey] = useState<string | null>(null);
  const refreshData = useCallback(async () => { setRefreshing(true); try { const data = await api<{ orders: Order[]; payments: Payment[]; exchanges: Exchange[]; invoices: Invoice[]; activities: Activity[]; clients: Client[]; quotes: Quote[]; invoiceDrafts: InvoiceDraft[] }>("/api/data"); setOrders(data.orders.map(order => { const client = (data.clients || []).find(client => client.id === order.clientId); return client ? { ...order, client: client.name, phone: client.phone } : order; })); setPayments(data.payments); setExchanges(data.exchanges || []); setInvoices(data.invoices || []); setActivities(data.activities || []); setClients(data.clients || []); setQuotes(data.quotes || []); setInvoiceDrafts(data.invoiceDrafts || []); setError(""); setLoaded(true); } catch (cause) { const message = cause instanceof Error ? cause.message : "No se pudieron cargar los pedidos."; setError(message); throw cause; } finally { setLoading(false); setRefreshing(false); } }, []);
  useEffect(() => { const initial = setTimeout(() => void refreshData().catch(() => {}), 0); const focus = () => { void refreshData().catch(() => {}); }; window.addEventListener("focus", focus); return () => { clearTimeout(initial); window.removeEventListener("focus", focus); }; }, [refreshData]);
  useEffect(() => { if (!notice) return; const timeout = setTimeout(() => setNotice(""), 5000); return () => clearTimeout(timeout); }, [notice]);
  const paidMap = useMemo(() => { const map = new Map<string, number>(); payments.forEach(item => map.set(item.orderId, (map.get(item.orderId) || 0) + (item.kind === "Devolución" ? -item.amountCents : item.amountCents))); return map; }, [payments]);
  const total = orders.reduce((sum, order) => sum + totalOf(order), 0), paid = payments.reduce((sum, payment) => sum + (payment.kind === "Devolución" ? -payment.amountCents : payment.amountCents), 0);
  const people = useMemo(() => { const map = new Map<string, { key: string; client: string; phone: string; total: number; paid: number; count: number }>(); orders.forEach(order => { const key = personKey(order, clients); const person = map.get(key) || { key, client: order.client, phone: order.phone, total: 0, paid: 0, count: 0 }; person.total += totalOf(order); person.paid += paidMap.get(order.id) || 0; person.count++; map.set(key, person); }); return [...map.values()].sort((a, b) => a.client.localeCompare(b.client, "es")); }, [orders, paidMap, clients]);
  const pending = people.reduce((sum, person) => sum + Math.max(0, person.total - person.paid), 0), credit = people.reduce((sum, person) => sum + Math.max(0, person.paid - person.total), 0);
  const search = normalize(query);
  const filtered = [...orders].filter(order => (!search || [order.client, order.article, order.variant, order.batch, order.phone, order.id, order.platform].some(value => normalize(value).includes(search))) && (status === "Todos" || order.status === status) && (!onlyPending || totalOf(order) > (paidMap.get(order.id) || 0)) && (!clientFilter || personKey(order, clients) === clientFilter) && (!dateFrom || order.date >= dateFrom) && (!dateTo || order.date <= dateTo)).sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id));
